// public/shared/casting/meters.js
init_meter_tactus();
function meterKind(meter) {
  const tactus = tactusOf(meter);
  if (tactus.compound) return "compound";
  const groups = Array.isArray(meter?.groups) && meter.groups.length ? meter.groups : null;
  return groups && new Set(groups).size > 1 ? "additive" : "simple";
}
var inThrees = (meter) => Number(meter?.subdivision) === 3 && Number(meter?.denominator) === 4 ? " in threes" : "";
var meterLabel = (meter) => `${meter?.numerator}/${meter?.denominator}${Array.isArray(meter?.groups) && meter.groups.length > 1 ? ` (${meter.groups.join("+")})` : ""}${inThrees(meter)}`;
function feltLabel(meter, { secondsPerTick: tick }) {
  const subdivision = Math.max(1, Number(meter?.subdivision) || 4);
  return `${meter?.numerator}/${meter?.denominator}${inThrees(meter)} felt ${feltBeats(meter, { secondsPerTick: tick }).map((beat) => Math.round(beat.length / subdivision * 100) / 100).join("+")}`;
}
var tickSecondsAt = (quarterBpm, meter) => secondsPerTick({ bpm: (Number(quarterBpm) || 100) * (Number(meter?.denominator) || 4) / 4, meter });

