function turbulenceEntry(model) {
  let entry3;
  try {
    entry3 = playerEntry(model, "flow.turbulence");
  } catch {
    return null;
  }
  return { value: entry3.value, unit: entry3.unit, kind: entry3.kind, what: "its flow's turbulent fluctuation, a share of the flow per root hertz" };
}

